function report(){return{source:'Real isolated HTTPS cloud and RC outbound connector; deterministic synthetic accounts/main adapter; development-loopback profile only',passed:checks.filter(x=>x.status==='PASS').length,failed:checks.filter(x=>x.status==='FAIL').length,checks};}
async function test(id,name,action){console.log('RUN '+id+' '+name);try{await action();checks.push({id,name,status:'PASS'});console.log('PASS '+id+' '+name);}catch(error){checks.push({id,name,status:'FAIL',error:error.stack});console.error('FAIL '+id+' '+error.stack);process.exitCode=1;}await fs.writeFile(path.join(out,'results.json'),JSON.stringify(report(),null,2));}
async function native(request){return await new Promise((resolve,reject)=>{const p=spawn(rcImage,['--dev-control',nonce,String(host.pid)],{stdio:['pipe','pipe','inherit'],windowsHide:false,env:childEnv});let text='';const timer=setTimeout(()=>{p.kill();reject(Error('Native timeout: '+request.op));},15000);p.stdout.on('data',b=>{text+=b;if(text.length>262144){p.kill();reject(Error('Native response limit'));}});p.once('error',e=>{clearTimeout(timer);reject(e);});p.once('exit',code=>{clearTimeout(timer);try{const value=JSON.parse(text);if(code||value.error)throw Error(value.error?.message||'Native control failed');resolve(value);}catch(e){reject(e);}});p.stdin.on('error',()=>{});p.stdin.end(JSON.stringify(request)+'\n');});}
function httpsCall(route,{method='GET',body,headers={},jar,originHeader=origin}={}){return new Promise((resolve,reject)=>{const bytes=body===undefined?null:Buffer.from(JSON.stringify(body));const h={...(bytes?{'Content-Type':'application/json','Content-Length':bytes.length}:{}),...(jar?.cookie?{Cookie:jar.cookie}:{}),...(originHeader===null?{}:{Origin:originHeader}),...headers};const request=https.request(new URL(route,origin),{method,headers:h,ca,rejectUnauthorized:true,timeout:10000},res=>{const chunks=[];let total=0;res.on('data',b=>{total+=b.length;if(total>4*1024*1024){res.destroy();reject(Error('Cloud HTTP body limit'));}else chunks.push(b);});res.once('error',reject);res.on('end',()=>{const data=Buffer.concat(chunks);let json;try{json=JSON.parse(data.toString());}catch{}if(jar&&res.headers['set-cookie']){const cookies=res.headers['set-cookie'];const value=cookies.find(x=>x.startsWith('__Host-tlachihuani-hosted='));if(value)jar.cookie=value.split(';')[0];}resolve({status:res.statusCode,headers:res.headers,bytes:data,json});});});request.once('error',reject);request.once('timeout',()=>request.destroy(Error('Cloud HTTPS timeout')));if(bytes)request.write(bytes);request.end();});}
async function bootstrap(){const jar={};const r=await httpsCall('/api/hosted/bootstrap',{jar});assert.equal(r.status,200);jar.csrf=r.json.csrf_token;assert.ok(jar.csrf);return{jar,response:r};}
async function login(user){const {jar}=await bootstrap();const r=await httpsCall('/api/hosted/login',{method:'POST',jar,headers:{'X-CSRF-Token':jar.csrf},body:{username:user.username,password:user.password}});assert.equal(r.status,200,'Valid fixture sign-in');const current=await httpsCall('/api/hosted/bootstrap',{jar});assert.equal(current.status,200);assert.ok(current.json.user);jar.csrf=current.json.csrf_token;return jar;}
async function route(jar,account,key,extra={}){return await httpsCall('/api/hosted/connections',{method:'POST',jar,headers:{'X-CSRF-Token':jar.csrf},body:{installation_id:installationId,binding_id:account.binding.id,device_public_key:key.spki,profile:'development-loopback',...extra}});}
function deviceKey(){const pair=generateKeyPairSync('ec',{namedCurve:'prime256v1'});return{...pair,spki:pair.publicKey.export({format:'der',type:'spki'}).toString('base64')};}

// A small test-only RFC6455 peer enables exact Origin/cookie/fragment/close tests.
// All sockets validate the test leaf certificate, are loopback-only and are owned here.
class Wire {
  constructor(socket){this.socket=socket;this.buffer=Buffer.alloc(0);this.queue=[];this.waiters=[];this.fragment=null;this.closed=false;ownedSockets.add(this);socket.on('data',b=>{this.buffer=Buffer.concat([this.buffer,b]);try{this.parse();}catch(e){this.fail(e);}});socket.on('error',e=>this.fail(e));socket.on('close',()=>{this.closed=true;this.fail(Error('WebSocket closed'));});}
  static async connect(route,headers={},protocol='tlachihuani.relay.v1',{onRequestSent}={}) {return await new Promise((resolve,reject)=>{const url=new URL(route,origin);assert.equal(url.hostname,'127.0.0.1');const socket=tls.connect({host:url.hostname,port:Number(url.port),ca,rejectUnauthorized:true,checkServerIdentity:(_,cert)=>tls.checkServerIdentity(url.hostname,cert)});const key=randomBytes(16).toString('base64');let buffer=Buffer.alloc(0);const timer=setTimeout(()=>{socket.destroy();reject(Error('WebSocket upgrade timeout'));},10000);const onError=e=>{clearTimeout(timer);reject(e);};const onClose=()=>{clearTimeout(timer);reject(Error('WebSocket upgrade closed'));};socket.once('error',onError);socket.once('close',onClose);socket.once('secureConnect',()=>{const fields={Host:url.host,Upgrade:'websocket',Connection:'Upgrade','Sec-WebSocket-Key':key,'Sec-WebSocket-Version':'13',...(protocol?{'Sec-WebSocket-Protocol':protocol}:{}),...headers};socket.write('GET '+url.pathname+url.search+' HTTP/1.1\r\n'+Object.entries(fields).map(([k,v])=>k+': '+v).join('\r\n')+'\r\n\r\n');onRequestSent?.();});const onData=b=>{buffer=Buffer.concat([buffer,b]);const pos=buffer.indexOf('\r\n\r\n');if(pos<0){if(buffer.length>16384){socket.destroy();reject(Error('Oversize upgrade headers'));}return;}clearTimeout(timer);socket.off('data',onData);socket.off('error',onError);socket.off('close',onClose);const lines=buffer.subarray(0,pos).toString().split('\r\n');const status=Number(lines[0].split(' ')[1]);const responseHeaders=Object.fromEntries(lines.slice(1).map(line=>{const i=line.indexOf(':');return[line.slice(0,i).toLowerCase(),line.slice(i+1).trim()];}));if(status!==101){socket.destroy();resolve({status,headers:responseHeaders,wire:null});return;}if(responseHeaders['sec-websocket-accept']!==createHash('sha1').update(key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64')){socket.destroy();reject(Error('Invalid WebSocket upgrade proof'));return;}const wire=new Wire(socket);wire.buffer=buffer.subarray(pos+4);try{wire.parse();resolve({status,headers:responseHeaders,wire});}catch(e){wire.close();reject(e);}};socket.on('data',onData);});}
  fail(error){this.error=error;for(const waiter of this.waiters.splice(0)){clearTimeout(waiter.timer);waiter.reject(error);}}
  emit(value){const waiter=this.waiters.shift();if(waiter){clearTimeout(waiter.timer);waiter.resolve(value);}else this.queue.push(value);}
  parse(){while(this.buffer.length>=2){const first=this.buffer[0],second=this.buffer[1],opcode=first&15,fin=!!(first&128);let size=second&127,offset=2;if(second&128)throw Error('Server sent masked frame');if(size===126){if(this.buffer.length<4)return;size=this.buffer.readUInt16BE(2);offset=4;}else if(size===127){if(this.buffer.length<10)return;const n=this.buffer.readBigUInt64BE(2);if(n>BigInt(2*1024*1024))throw Error('Server frame exceeds test limit');size=Number(n);offset=10;}if(this.buffer.length<offset+size)return;const payload=this.buffer.subarray(offset,offset+size);this.buffer=this.buffer.subarray(offset+size);if(opcode===8){this.emit({close:true,code:payload.length>=2?payload.readUInt16BE(0):1005});this.socket.end();continue;}if(opcode===9){this.send(payload,10);continue;}if(opcode===10)continue;if(opcode===0){if(!this.fragment)throw Error('Unexpected continuation');this.fragment.parts.push(payload);if(fin){const f=this.fragment;this.fragment=null;this.deliver(f.opcode,Buffer.concat(f.parts));}}else if(!fin)this.fragment={opcode,parts:[payload]};else this.deliver(opcode,payload);}}
  deliver(opcode,bytes){if(opcode===1){let json;try{json=JSON.parse(bytes.toString());}catch{}this.emit({text:bytes.toString(),json,bytes,opcode});}else this.emit({bytes,opcode});}
  send(value,opcode=1,{fin=true,masked=true}={}){const data=Buffer.isBuffer(value)?value:Buffer.from(typeof value==='string'?value:JSON.stringify(value));const ext=data.length<126?0:data.length<65536?2:8;const h=Buffer.alloc(2+ext+(masked?4:0));h[0]=(fin?128:0)|opcode;h[1]=(masked?128:0)|(ext===0?data.length:ext===2?126:127);if(ext===2)h.writeUInt16BE(data.length,2);if(ext===8)h.writeBigUInt64BE(BigInt(data.length),2);let payload=data;if(masked){const mask=randomBytes(4);mask.copy(h,2+ext);payload=Buffer.from(data);for(let i=0;i<payload.length;i++)payload[i]^=mask[i%4];}this.socket.write(Buffer.concat([h,payload]));}
  receive(timeout=10000){if(this.queue.length)return Promise.resolve(this.queue.shift());if(this.closed||this.error)return Promise.reject(this.error||Error('Socket closed'));return new Promise((resolve,reject)=>{const waiter={resolve,reject};waiter.timer=setTimeout(()=>{this.waiters=this.waiters.filter(x=>x!==waiter);reject(Error('WebSocket message timeout'));},timeout);this.waiters.push(waiter);});}
  async denied(){try{const m=await this.receive(7000);return m.close||m.json?.type==='error'||m.json?.error;}catch(e){if(this.closed||/closed|ECONNRESET/.test(e.message))return true;throw e;}}
  close(){if(!this.closed){try{this.send(Buffer.from([3,232]),8);}catch{}this.socket.destroy();}ownedSockets.delete(this);}
}
class Tunnel {
  constructor(wire){this.wire=wire;this.pending=new Map();this.running=true;this.pump=this.read();}
  async read(){try{while(this.running){const message=await this.wire.receive(120000).catch(error=>{if(this.running&&!this.pending.size&&error.message==='WebSocket message timeout')return null;throw error;});if(!message)continue;if(message.close)throw Error('Relay closed');const v=message.json;if(!v?.id)continue;const p=this.pending.get(v.id);if(!p)continue;if(v.type==='response'){p.status=v.status;p.headers=v.headers||{};}else if(v.type==='chunk'){const b=Buffer.from(v.data,'base64');p.size+=b.length;if(p.size>65*1024*1024)throw Error('Response memory bound');p.chunks.push(b);}else if(v.type==='error'){this.pending.delete(v.id);clearTimeout(p.timer);p.resolve({status:v.status||500,json:{error:{code:v.code}},headers:{},bytes:Buffer.alloc(0)});}else if(v.type==='end'){this.pending.delete(v.id);clearTimeout(p.timer);const bytes=Buffer.concat(p.chunks);let json;try{json=JSON.parse(bytes.toString());}catch{}p.resolve({status:p.status,headers:p.headers,bytes,json});}}}catch(e){this.running=false;for(const p of this.pending.values()){clearTimeout(p.timer);p.reject(e);}this.pending.clear();}}
  request(route,{method='GET',body,headers={}}={}){if(!this.running)return Promise.reject(Error('Test relay is closed'));const id=guid();return new Promise((resolve,reject)=>{const p={resolve,reject,chunks:[],size:0,status:0,headers:{}};p.timer=setTimeout(()=>{this.pending.delete(id);this.wire.send({type:'cancel',id});reject(Error('Tunnel request timeout: '+route.split('?')[0]));},20000);this.pending.set(id,p);this.wire.send({type:'request',id,method,path:route,headers:{...(body===undefined||Object.keys(headers).some(k=>k.toLowerCase()==='content-type')?{}:{'Content-Type':'application/json'}),...headers},body:body===undefined?null:JSON.stringify(body)});});}
  close(){this.running=false;this.wire.close();}
}
async function connect(jar,account,key){const ticket=await route(jar,account,key);assert.equal(ticket.status,201);const ws=await Wire.connect('/relay/client',{Origin:origin,Cookie:jar.cookie});assert.equal(ws.status,101);ws.wire.send({ticket:ticket.json.ticket});const ready=await ws.wire.receive(15000);assert.equal(ready.json?.type,'ready','Connector paired the admitted browser');return{tunnel:new Tunnel(ws.wire),ticket:ticket.json.ticket};}
async function establish(jar,account){const key=deviceKey();const {tunnel}=await connect(jar,account,key);const invitation=await native({op:'invite',binding_id:account.binding.id,scopes:['chat','monitor']});const enrolled=await tunnel.request('/api/rc/v1/enrollments',{method:'POST',body:{invitation:invitation.invitation,name:'Hosted '+account.edition,public_key:key.spki}});assert.equal(enrolled.status,202);assert.ok(enrolled.json.fingerprint);await native({op:'approve',enrollment_id:enrolled.json.id,fingerprint:enrolled.json.fingerprint});const approved=await tunnel.request('/api/rc/v1/enrollments/poll',{method:'POST',body:{id:enrolled.json.id,poll_secret:enrolled.json.poll_secret}});assert.equal(approved.json.status,'approved');const challenge=await tunnel.request('/api/rc/v1/sessions/challenges',{method:'POST',body:{device_id:approved.json.device_id}});assert.equal(challenge.status,200);const signature=sign('sha256',Buffer.from(challenge.json.challenge,'base64'),{key:key.privateKey,dsaEncoding:'ieee-p1363'}).toString('base64');const session=await tunnel.request('/api/rc/v1/sessions',{method:'POST',body:{device_id:approved.json.device_id,challenge_id:challenge.json.id,signature}});assert.equal(session.status,200);assert.ok(session.json.access_token);return{key,tunnel,deviceId:approved.json.device_id,token:session.json.access_token,headers:{Authorization:'Bearer '+session.json.access_token}};}
async function next(account,kind){return await poll(async()=>{const value=await native({op:'adapter-next',adapter_id:account.adapter});if(!value.operation)return false;assert.equal(value.operation.kind,kind);assert.equal(value.operation.binding_id,account.binding.id);return value.operation;},'isolated '+kind,10000);}
async function submit(client,account,text){const idem=guid();const r=await client.tunnel.request('/api/rc/v1/operations',{method:'POST',headers:{...client.headers,'Idempotency-Key':idem},body:{operation:'conversation.submit',payload:{text},deadline_seconds:120}});assert.ok([200,202].includes(r.status));const operation=await next(account,'conversation.submit');return{receipt:r.json,operation,idem};}

async function knownSession(tunnel,key,deviceId){const c=await tunnel.request('/api/rc/v1/sessions/challenges',{method:'POST',body:{device_id:deviceId}});assert.equal(c.status,200);const signature=sign('sha256',Buffer.from(c.json.challenge,'base64'),{key:key.privateKey,dsaEncoding:'ieee-p1363'}).toString('base64');const s=await tunnel.request('/api/rc/v1/sessions',{method:'POST',body:{device_id:deviceId,challenge_id:c.json.id,signature}});assert.equal(s.status,200);return s.json.access_token;}
async function wsDenied(route,headers,protocol){const result=await Wire.connect(route,headers,protocol);if(result.wire)result.wire.close();assert.ok([400,401,403,404].includes(result.status),'Unauthorized upgrade denied before101; got '+result.status);}
async function expiredChannel(wire){assert.ok(await wire.denied(),'Peer closed/rejected the invalid channel');wire.close();}
const ownedExited=child=>!child||child.exitCode!==null||child.signalCode!==null;
async function waitOwnedExit(child,label,timeout=10000){if(ownedExited(child))return;await poll(()=>ownedExited(child),label,timeout);}
let forcedCloudStop=false;
async function stopOwnedCloud(child,label){
  if(ownedExited(child))return;
  try{child.stdin.end('stop\n');await waitOwnedExit(child,label,40000);}
  catch(error){if(!ownedExited(child)){forcedCloudStop=true;child.kill();await waitOwnedExit(child,label+' after owned kill');}throw error;}
  assert.equal(child.signalCode,null,'Cloud stopped gracefully without a kill signal');
  assert.equal(child.exitCode,0,'Cloud completed normal certificate disposal');
}

