  const first=accounts[0],second=accounts[1];

  await test('SEC01','Bootstrap labels the weaker isolated development profile truthfully',async()=>{const {response}=await bootstrap();assert.equal(response.json.mode,'hosted');assert.equal(response.json.profile,'development-loopback');assert.equal(response.json.post_quantum,false);assert.equal(response.json.public_remote_enabled,false);assert.equal(response.json.user,null);assert.match(response.headers['cache-control']||'',/no-store/i);});
