  await test('SEC03','Login rejects missing CSRF proof',async()=>{const {jar}=await bootstrap();const r=await httpsCall('/api/hosted/login',{method:'POST',jar,body:{username:first.user.username,password:first.user.password}});assert.equal(r.status,403);});
  await test('SEC04','Sibling/hostile origins cannot sign in with valid credentials',async()=>{const {jar}=await bootstrap();const r=await httpsCall('/api/hosted/login',{method:'POST',jar,originHeader:'https://xaiht.org',headers:{'X-CSRF-Token':jar.csrf},body:{username:first.user.username,password:first.user.password}});assert.equal(r.status,403);});
  await test('SEC05','Incorrect passwords create no authenticated session',async()=>{const {jar}=await bootstrap();const r=await httpsCall('/api/hosted/login',{method:'POST',jar,headers:{'X-CSRF-Token':jar.csrf},body:{username:first.user.username,password:'incorrect isolated password'}});assert.equal(r.status,401);const b=await httpsCall('/api/hosted/bootstrap',{jar});assert.equal(b.json.user,null);});
